 }

 #container .cih-select:hover {
 background-color: #e2eef3;
 }

 #container .cih-select option[disabled] {
 display: none;
 }

 #container .cih-anchor {
 text-decoration: none;
 color: #0f206c;
 transition: 0.2s;
 }

 #container .cih-anchor:hover {
 color: #acc74f;
 }

 #container .cih-expand {
 -webkit-user-select: none;
